export interface SpikoInvestorApiError<Tag extends string, E> {
  readonly _tag: Tag
  readonly request: HttpClientRequest.HttpClientRequest
  readonly response: HttpClientResponse.HttpClientResponse
  readonly cause: E
}

class SpikoInvestorApiErrorImpl extends Data.Error<{
  _tag: string
  cause: any
  request: HttpClientRequest.HttpClientRequest
  response: HttpClientResponse.HttpClientResponse
}> {}

export const SpikoInvestorApiError = <Tag extends string, E>(
  tag: Tag,
  cause: E,
  response: HttpClientResponse.HttpClientResponse,
): SpikoInvestorApiError<Tag, E> =>
  new SpikoInvestorApiErrorImpl({
    _tag: tag,
    cause,
    response,
    request: response.request,
  }) as any
